from pathlib import Path
web=Path('F:/Afrigoals/Afrigoals_ecommerce')
def put(name,s):
 p=web/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s,encoding='utf-8')
for route,backend,methods in [
 ('admin/commerce/overview','/admin/commerce/overview',['GET']),('admin/iotec/wallet','/admin/iotec/wallet',['GET']),
 ('admin/assistant','/admin/assistant',['POST']),('admin/partner-stores','/admin/partner-stores',['GET','PUT']),
 ('admin/email-automation','/admin/email-automation',['GET','PUT']),('admin/email-campaigns','/admin/email-campaigns',['GET','PUT'])]:
 s='import{NextResponse}from"next/server";import{authedFetch}from"@/lib/api/proxy";\nexport const maxDuration=120;\n'
 for method in methods:
  init='' if method=='GET' else ',{method:"'+method+'",headers:{"Content-Type":"application/json"},body:await request.text()}'
  s+=f'''export async function {method}({'request:Request' if method!='GET' else ''}){{const response=await authedFetch("{backend}"{init});return new NextResponse(await response.text(),{{status:response.status,headers:{{"Content-Type":"application/json","Cache-Control":"no-store"}}}})}}\n'''
 put(f'app/api/{route}/route.ts',s)
put('app/api/admin/email-campaigns/[id]/deliveries/route.ts','''import{NextResponse}from"next/server";import{authedFetch}from"@/lib/api/proxy";
export async function GET(_request:Request,{params}:{params:Promise<{id:string}>}){const{id}=await params;const r=await authedFetch(`/admin/email-campaigns/${encodeURIComponent(id)}/deliveries`);return new NextResponse(await r.text(),{status:r.status,headers:{"Content-Type":"application/json","Cache-Control":"no-store"}})}
''')
put('app/api/chat/route.ts','''import{createUIMessageStream,createUIMessageStreamResponse,type UIMessage}from"ai";
import{cookies}from"next/headers";import{AUTH_COOKIE_NAME}from"@/lib/auth/constants";import{getBackendApiBaseUrl}from"@/lib/api/backend";
export const maxDuration=120;
export async function POST(request:Request){
 let input:{messages?:UIMessage[]};try{input=await request.json()}catch{return Response.json({error:"Invalid chat request"},{status:400})}
 if(!Array.isArray(input.messages)||input.messages.length>40||JSON.stringify(input.messages).length>100000)return Response.json({error:"Invalid chat history"},{status:400});
 const messages=input.messages.filter(m=>m.role==="user"||m.role==="assistant").map(m=>({role:m.role,content:(m.parts??[]).filter(p=>p.type==="text").map(p=>p.type==="text"?p.text:"").join("\\n")})).filter(m=>m.content.trim());
 if(!messages.length)return Response.json({error:"A message is required"},{status:400});
 const token=(await cookies()).get(AUTH_COOKIE_NAME)?.value;
 const stream=createUIMessageStream({execute:async({writer})=>{
  writer.write({type:"start",messageId:crypto.randomUUID()});writer.write({type:"text-start",id:"answer"});
  try{const response=await fetch(`${getBackendApiBaseUrl()}/assistant/chat`,{method:"POST",headers:{"Content-Type":"application/json",...(token?{Authorization:`Bearer ${token}`}:{})},body:JSON.stringify({messages}),cache:"no-store"});const data=await response.json();writer.write({type:"text-delta",id:"answer",delta:response.ok?data.answer:data.error||"The assistant is temporarily unavailable."})}
  catch{writer.write({type:"text-delta",id:"answer",delta:"The assistant is temporarily unavailable. Please try again."})}
  writer.write({type:"text-end",id:"answer"});writer.write({type:"finish",finishReason:"stop"});
 }});return createUIMessageStreamResponse({stream});
}
''')
put('app/(admin)/admin/insights/page.tsx','''"use client";
import{useEffect,useState}from"react";import ReactMarkdown from"react-markdown";import{Button}from"@/components/ui/button";import{formatPrice}from"@/lib/utils";
type Product={productId:string;name:string;stock:number;units:number;revenue:number;reviewCount:number;averageRating:number};
type Overview={report:{totals:{paidOrders:number;productSales:number;deliveryFees:number;riderPayouts:number;deliveryCommission:number;outstandingCod:number}};performance:Product[];daily:{day:string;revenue:number;orders:number}[];iotecReceived:number;customers:number};
type Wallet={actualBalance:number;name:string;currency:string;checkedAt:string};
export default function InsightsPage(){
 const[data,setData]=useState<Overview|null>(null);const[wallet,setWallet]=useState<Wallet|null>(null);const[error,setError]=useState("");const[walletError,setWalletError]=useState("");const[loading,setLoading]=useState(false);const[question,setQuestion]=useState("Which products should we promote and which need attention? Explain using recorded sales and stock.");const[answer,setAnswer]=useState("");const[thinking,setThinking]=useState(false);
 async function load(){setLoading(true);setError("");setWalletError("");await Promise.all([
  fetch("/api/admin/commerce/overview",{cache:"no-store"}).then(async r=>{const body=await r.json();if(!r.ok)throw Error(body.error);setData(body)}).catch(e=>setError(e.message)),
  fetch("/api/admin/iotec/wallet",{cache:"no-store"}).then(async r=>{const body=await r.json();if(!r.ok)throw Error(body.error);setWallet(body)}).catch(e=>{setWallet(null);setWalletError(e.message)}),
 ]);setLoading(false)}
 useEffect(()=>{void load()},[]);
 async function ask(e:React.FormEvent){e.preventDefault();setThinking(true);try{const r=await fetch("/api/admin/assistant",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({question})});const body=await r.json();if(!r.ok)throw Error(body.error);setAnswer(body.answer)}catch(e){setAnswer(e instanceof Error?e.message:"Could not answer")}finally{setThinking(false)}}
 const max=Math.max(1,...(data?.daily.map(d=>d.revenue)??[]));const best=data?.performance.filter(p=>p.units>0).slice(0,8)??[];const maxUnits=Math.max(1,...best.map(p=>p.units));
 return <main className="space-y-6 p-6"><div className="flex flex-wrap items-center justify-between gap-4"><h1 className="text-2xl font-semibold">Commerce insights</h1><Button onClick={()=>void load()} disabled={loading}>{loading?"Refreshing…":"Refresh reports and wallet"}</Button></div>{error&&<p role="alert" className="text-red-600">{error}</p>}
 <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[
  ["Live IOTEC wallet",wallet?formatPrice(wallet.actualBalance,wallet.currency.toLowerCase()):"Unavailable"],
  ["Verified IOTEC collections",data?formatPrice(data.iotecReceived):"…"],
  ["Paid product sales",data?formatPrice(data.report.totals.productSales):"…"],
  ["Verified clients",data?String(data.customers):"…"],
 ].map(([label,value])=><section key={label} className="rounded-xl border bg-white p-5 dark:bg-zinc-950"><h2 className="text-sm text-zinc-500">{label}</h2><p className="mt-2 text-2xl font-semibold">{value}</p></section>)}</div>
 <p className="text-sm text-zinc-500">The wallet is a live provider balance. Collections are payments verified in Afrigoals records and can differ because of fees, withdrawals or other wallet activity.{wallet&&` Wallet checked ${new Date(wallet.checkedAt).toLocaleString()}.`}</p>{walletError&&<p role="status" className="rounded border border-amber-300 bg-amber-50 p-4 text-amber-900">{walletError}</p>}
 {data&&<><div className="grid gap-4 lg:grid-cols-2"><section className="rounded-xl border p-5"><h2 className="font-semibold">Daily paid revenue · last 30 days</h2><p className="text-sm text-zinc-500">Includes delivery. Dates with payments are shown.</p>{data.daily.length?<svg role="img" aria-label="Daily paid revenue chart" viewBox="0 0 720 250" className="mt-4 w-full"><title>Daily paid order revenue</title>{data.daily.map((d,i)=>{const width=640/data.daily.length;const height=d.revenue/max*170;return <g key={d.day}><rect x={45+i*width} y={190-height} width={Math.max(2,width-4)} height={height} fill="#4263eb"><title>{d.day}: {formatPrice(d.revenue)}, {d.orders} paid orders</title></rect>{(i===0||i===data.daily.length-1)&&<text x={45+i*width} y="215" fontSize="12">{d.day.slice(0,10)}</text>}</g>})}<text x="45" y="20" fontSize="12">Peak: {formatPrice(max)}</text></svg>:<p className="py-10 text-zinc-500">No paid revenue recorded in this period.</p>}</section><section className="rounded-xl border p-5"><h2 className="font-semibold">Top products by paid units</h2><div className="mt-4 space-y-3">{best.map(p=><div key={p.productId}><div className="flex justify-between gap-4 text-sm"><span>{p.name}</span><span>{p.units} sold</span></div><div className="mt-1 h-3 rounded bg-zinc-100"><div className="h-3 rounded bg-emerald-600" style={{width:`${p.units/maxUnits*100}%`}}/></div></div>)}{!best.length&&<p>No paid product sales yet.</p>}</div></section></div>
 <section className="overflow-x-auto rounded-xl border"><h2 className="p-5 font-semibold">Current catalog performance</h2><table className="w-full text-left text-sm"><thead><tr>{["Product","Paid units","Product revenue","Stock","Reviews"].map(label=><th className="p-3" key={label}>{label}</th>)}</tr></thead><tbody>{data.performance.map(p=><tr className="border-t" key={p.productId}><td className="p-3">{p.name}</td><td>{p.units}</td><td>{formatPrice(p.revenue)}</td><td>{p.stock}</td><td>{p.reviewCount?`${p.averageRating.toFixed(1)}/5 (${p.reviewCount})`:"No reviews"}</td></tr>)}</tbody></table></section><section className="rounded-xl border p-5"><h2 className="font-semibold">Products with no recorded paid sales</h2><p className="mt-1 text-sm text-zinc-500">Check availability, listing age and exposure before treating zero sales as poor demand.</p><ul className="mt-3 list-inside list-disc">{data.performance.filter(p=>p.units===0).map(p=><li key={p.productId}>{p.name} · {p.stock} in stock</li>)}</ul></section></>}
 <section className="rounded-xl border p-5"><h2 className="font-semibold">Ask the commerce AI</h2><p className="text-sm text-zinc-500">Uses the scout AI provider with store sales and inventory evidence. It can advise and draft copy; it cannot change records or send campaigns.</p><form onSubmit={ask} className="mt-4 space-y-3"><label htmlFor="admin-question" className="block">Question</label><textarea id="admin-question" required maxLength={10000} rows={3} className="w-full rounded border p-3" value={question} onChange={e=>setQuestion(e.target.value)}/><Button disabled={thinking}>{thinking?"Analysing…":"Ask AI"}</Button></form>{answer&&<div className="prose mt-5 max-w-none dark:prose-invert"><ReactMarkdown>{answer}</ReactMarkdown></div>}</section></main>
}
''')
put('app/(admin)/admin/partner-stores/page.tsx','''"use client";
import{useEffect,useState}from"react";import{Button}from"@/components/ui/button";
type Store={id?:string;name:string;description:string;keywords:string;phone:string;website:string;instagram:string;tiktok:string;whatsapp:string;active:boolean};
const empty:Store={name:"",description:"",keywords:"",phone:"",website:"",instagram:"",tiktok:"",whatsapp:"",active:true};
export default function PartnerStoresPage(){const[stores,setStores]=useState<Store[]>([]);const[form,setForm]=useState<Store>(empty);const[error,setError]=useState("");const[busy,setBusy]=useState(false);
 async function load(){const r=await fetch("/api/admin/partner-stores",{cache:"no-store"});const body=await r.json();if(!r.ok)throw Error(body.error);setStores(body)}useEffect(()=>{load().catch(e=>setError(e.message))},[]);
 async function save(e:React.FormEvent){e.preventDefault();setBusy(true);setError("");try{const r=await fetch("/api/admin/partner-stores",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(form)});const body=await r.json();if(!r.ok)throw Error(body.error);setForm(empty);await load()}catch(e){setError(e instanceof Error?e.message:"Could not save store")}finally{setBusy(false)}}
 return <main className="max-w-4xl space-y-6 p-6"><h1 className="text-2xl font-semibold">Partner store directory</h1><p>List external stores such as Vargo Sports, the products or teams they specialise in, and their real contact links. The shopping assistant can suggest active entries when Afrigoals has no matching product. Availability is confirmed with the external store.</p>{error&&<p role="alert" className="text-red-600">{error}</p>}<form onSubmit={save} className="space-y-4 rounded-xl border p-5"><h2 className="font-semibold">{form.id?"Edit store":"Add store"}</h2><div className="grid gap-4 sm:grid-cols-2">{([['name','Store name'],['keywords','Products / teams / keywords (e.g. Manchester United, Arsenal jerseys)'],['phone','Phone'],['website','Website URL'],['instagram','Instagram URL'],['tiktok','TikTok URL'],['whatsapp','WhatsApp URL']]as const).map(([key,label])=><label key={key} htmlFor={key} className="block text-sm">{label}<input id={key} type={['website','instagram','tiktok','whatsapp'].includes(key)?"url":"text"} required={key==='name'} className="mt-1 block w-full rounded border p-2" value={form[key]} onChange={e=>setForm({...form,[key]:e.target.value})}/></label>)}</div><label htmlFor="store-description" className="block">Description<textarea id="store-description" rows={3} className="mt-1 block w-full rounded border p-2" value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></label><label className="flex items-center gap-2"><input type="checkbox" checked={form.active} onChange={e=>setForm({...form,active:e.target.checked})}/>Visible to customers and the assistant</label><div className="flex gap-3"><Button disabled={busy}>Save store</Button><Button type="button" variant="outline" onClick={()=>setForm(empty)}>New entry</Button></div></form>{stores.map(store=><article key={store.id} className="flex items-center justify-between gap-4 rounded border p-4"><div><h2 className="font-semibold">{store.name} · {store.active?"Active":"Hidden"}</h2><p>{store.keywords}</p><p>{store.phone}</p></div><Button variant="outline" onClick={()=>setForm(store)}>Edit</Button></article>)}</main>
}
''')
put('app/(app)/partner-stores/page.tsx','''import{apiGet}from"@/lib/api/client";
type Store={id:string;name:string;description:string;keywords:string;phone:string;website:string;instagram:string;tiktok:string;whatsapp:string};
export const dynamic="force-dynamic";
export default async function PartnerStoresPage(){let stores:Store[]=[];let error="";try{stores=await apiGet<Store[]>("/partner-stores")}catch{error="The store directory is temporarily unavailable."}
 return <main className="mx-auto max-w-5xl space-y-6 p-6"><h1 className="text-2xl font-semibold">Other stores to explore</h1><p>External stores listed by Afrigoals. Contact each store directly to confirm products, availability and prices.</p>{error&&<p role="alert">{error}</p>}{!error&&!stores.length&&<p>No external stores have been listed yet.</p>}<div className="grid gap-4 md:grid-cols-2">{stores.map(store=><article key={store.id} className="space-y-3 rounded-xl border p-5"><h2 className="text-lg font-semibold">{store.name}</h2><p>{store.description}</p><p className="text-sm text-zinc-500">{store.keywords}</p>{store.phone&&<p>Phone: {store.phone}</p>}<div className="flex flex-wrap gap-4">{([['Website',store.website],['Instagram',store.instagram],['TikTok',store.tiktok],['WhatsApp',store.whatsapp]]as const).filter(([,url])=>url).map(([name,url])=><a key={name} className="underline" href={url} target="_blank" rel="noopener noreferrer">{name}</a>)}</div></article>)}</div></main>
}
''')
put('app/(admin)/admin/email-campaigns/page.tsx','''"use client";
import{useEffect,useState}from"react";import{Button}from"@/components/ui/button";
type Campaign={id:string;subject:string;body:string;status:string;scheduledAt:string|null};type Delivery={id:string;email:string;status:string;error?:string;sentAt?:string};
export default function CampaignsPage(){const[campaigns,setCampaigns]=useState<Campaign[]>([]);const[deliveries,setDeliveries]=useState<Delivery[]>([]);const[enabled,setEnabled]=useState(false);const[configured,setConfigured]=useState(false);const[subject,setSubject]=useState("");const[body,setBody]=useState("");const[scheduled,setScheduled]=useState("");const[message,setMessage]=useState("");const[busy,setBusy]=useState(false);
 async function load(){const[cr,ar]=await Promise.all([fetch("/api/admin/email-campaigns",{cache:"no-store"}),fetch("/api/admin/email-automation",{cache:"no-store"})]);const[c,a]=await Promise.all([cr.json(),ar.json()]);if(!cr.ok||!ar.ok)throw Error(c.error||a.error);setCampaigns(c);setEnabled(a.enabled);setConfigured(a.providerConfigured)}useEffect(()=>{load().catch(e=>setMessage(e.message))},[]);
 async function save(status:string){setBusy(true);try{if(status==='scheduled'&&!scheduled)throw Error("Choose a future send time");const r=await fetch("/api/admin/email-campaigns",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({subject,body,status,scheduledAt:scheduled?new Date(scheduled).toISOString():null})});const data=await r.json();if(!r.ok)throw Error(data.error);setMessage(status==='draft'?"Draft saved. No email has been sent.":"Campaign scheduled. It will run only while automation is enabled.");await load()}catch(e){setMessage(e instanceof Error?e.message:"Could not save")}finally{setBusy(false)}}
 async function toggle(){setBusy(true);try{const r=await fetch("/api/admin/email-automation",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({enabled:!enabled})});const data=await r.json();if(!r.ok)throw Error(data.error);await load()}catch(e){setMessage(e instanceof Error?e.message:"Could not change automation")}finally{setBusy(false)}}
 async function draftAI(){setBusy(true);try{const r=await fetch("/api/admin/assistant",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({question:"Draft a concise marketing email about products actually in stock. Use current sales evidence, no invented discounts, and plain text without a subject line. Do not send it."})});const data=await r.json();if(!r.ok)throw Error(data.error);setBody(data.answer);setMessage("AI draft generated. Review it before saving or scheduling.")}catch(e){setMessage(e instanceof Error?e.message:"Could not draft")}finally{setBusy(false)}}
 async function inspect(id:string){try{const r=await fetch(`/api/admin/email-campaigns/${id}/deliveries`,{cache:"no-store"});const data=await r.json();if(!r.ok)throw Error(data.error);setDeliveries(data)}catch(e){setMessage(e instanceof Error?e.message:"Could not load delivery status")}}
 return <main className="max-w-5xl space-y-6 p-6"><h1 className="text-2xl font-semibold">Email campaigns and automation</h1><section className="space-y-3 rounded-xl border p-5"><p>Automation: <strong>{enabled?"On":"Off"}</strong> · Email provider: {configured?"Configured":"Not configured"}</p><p className="text-sm text-zinc-500">Scheduled campaigns go to verified client/vendor accounts that have not unsubscribed. Order and security emails continue independently. Failed or uncertain deliveries are recorded for review rather than automatically duplicated.</p><Button disabled={busy||(!enabled&&!configured)} variant="outline" onClick={()=>void toggle()}>{enabled?"Pause automation":"Enable scheduled sending"}</Button></section>{message&&<p role="status" className="rounded border p-4">{message}</p>}<form onSubmit={e=>{e.preventDefault();void save('draft')}} className="space-y-4 rounded-xl border p-5"><h2 className="font-semibold">Create campaign</h2><label htmlFor="campaign-subject" className="block">Subject<input id="campaign-subject" required maxLength={200} value={subject} onChange={e=>setSubject(e.target.value)} className="mt-1 block w-full rounded border p-2"/></label><label htmlFor="campaign-body" className="block">Message<textarea id="campaign-body" required maxLength={20000} rows={8} value={body} onChange={e=>setBody(e.target.value)} className="mt-1 block w-full rounded border p-3"/></label><label htmlFor="campaign-time" className="block">Send time (your local time)<input id="campaign-time" type="datetime-local" value={scheduled} onChange={e=>setScheduled(e.target.value)} className="mt-1 block rounded border p-2"/></label><div className="flex flex-wrap gap-3"><Button disabled={busy}>Save draft</Button><Button type="button" variant="outline" disabled={busy} onClick={()=>void draftAI()}>Draft with AI</Button><Button type="button" disabled={busy||!subject.trim()||!body.trim()} onClick={()=>void save('scheduled')}>Schedule campaign</Button></div></form><section className="space-y-3"><h2 className="font-semibold">Campaign history</h2>{campaigns.map(c=><article key={c.id} className="flex flex-wrap justify-between gap-3 rounded border p-4"><div><h3>{c.subject}</h3><p>{c.status} · {c.scheduledAt?new Date(c.scheduledAt).toLocaleString():"Not scheduled"}</p></div><Button variant="outline" onClick={()=>void inspect(c.id)}>View client delivery steps</Button></article>)}</section>{deliveries.length>0&&<section className="overflow-x-auto rounded border"><table className="w-full text-left text-sm"><thead><tr><th className="p-3">Client</th><th>Step</th><th>Sent at / review</th></tr></thead><tbody>{deliveries.map(d=><tr key={d.id} className="border-t"><td className="p-3">{d.email}</td><td>{d.status}</td><td>{d.sentAt?new Date(d.sentAt).toLocaleString():d.error||"Pending"}</td></tr>)}</tbody></table></section>}</main>
}
''')
